-- Optional, explicit import into the selected NEX MARKET database.
-- Creates published test products with placeholder prices and stock. Orders are REAL database records.
-- Inserts only; existing rows are never modified. Review and back up before execution.
begin;

with categories_input as (
 select * from jsonb_to_recordset('[{"name":"Texnika","slug":"nex-sinov-texnika","sort_order":100},{"name":"Uy uchun","slug":"nex-sinov-uy","sort_order":101},{"name":"Go‘zallik","slug":"nex-sinov-gozallik","sort_order":102},{"name":"Aksessuarlar","slug":"nex-sinov-uslub","sort_order":103},{"name":"Oshxona","slug":"nex-sinov-oshxona","sort_order":104},{"name":"Sport","slug":"nex-sinov-sport","sort_order":105}]'::jsonb) as x(name text, slug text, sort_order int)
), inserted_categories as (
 insert into categories(name, slug, sort_order, is_active)
 select name, slug, sort_order, true from categories_input
 on conflict do nothing returning id, slug
), category_map as (
 select id, slug from inserted_categories
 union all
 select c.id, c.slug from categories c join categories_input i on i.slug=c.slug
), products_input as (
 select * from jsonb_to_recordset('[{"name":"Simsiz quloqchin","slug":"nex-sinov-01","sku":"NEX-SINOV-01","price":249000,"main_image":"/images/items/01.webp","category_slug":"nex-sinov-texnika"},{"name":"Portativ karnay","slug":"nex-sinov-02","sku":"NEX-SINOV-02","price":329000,"main_image":"/images/items/02.webp","category_slug":"nex-sinov-texnika"},{"name":"Aqlli soat","slug":"nex-sinov-03","sku":"NEX-SINOV-03","price":589000,"main_image":"/images/items/03.webp","category_slug":"nex-sinov-texnika"},{"name":"Telefon uchun quvvatlagich","slug":"nex-sinov-04","sku":"NEX-SINOV-04","price":89000,"main_image":"/images/items/04.webp","category_slug":"nex-sinov-texnika"},{"name":"Simsiz sichqoncha","slug":"nex-sinov-05","sku":"NEX-SINOV-05","price":129000,"main_image":"/images/items/05.webp","category_slug":"nex-sinov-texnika"},{"name":"Stol chirog‘i","slug":"nex-sinov-06","sku":"NEX-SINOV-06","price":185000,"main_image":"/images/items/06.webp","category_slug":"nex-sinov-uy"},{"name":"Yumshoq pled","slug":"nex-sinov-07","sku":"NEX-SINOV-07","price":220000,"main_image":"/images/items/07.webp","category_slug":"nex-sinov-uy"},{"name":"Dekorativ vaza","slug":"nex-sinov-08","sku":"NEX-SINOV-08","price":119000,"main_image":"/images/items/08.webp","category_slug":"nex-sinov-uy"},{"name":"Aroma diffuzor","slug":"nex-sinov-09","sku":"NEX-SINOV-09","price":165000,"main_image":"/images/items/09.webp","category_slug":"nex-sinov-uy"},{"name":"Saqlash savati","slug":"nex-sinov-10","sku":"NEX-SINOV-10","price":99000,"main_image":"/images/items/10.webp","category_slug":"nex-sinov-uy"},{"name":"Namlagich krem","slug":"nex-sinov-11","sku":"NEX-SINOV-11","price":115000,"main_image":"/images/items/11.svg","category_slug":"nex-sinov-gozallik"},{"name":"Yuz uchun serum","slug":"nex-sinov-12","sku":"NEX-SINOV-12","price":139000,"main_image":"/images/items/12.svg","category_slug":"nex-sinov-gozallik"},{"name":"Soch parvarishi to‘plami","slug":"nex-sinov-13","sku":"NEX-SINOV-13","price":179000,"main_image":"/images/items/13.svg","category_slug":"nex-sinov-gozallik"},{"name":"Qo‘l kremi","slug":"nex-sinov-14","sku":"NEX-SINOV-14","price":59000,"main_image":"/images/items/14.svg","category_slug":"nex-sinov-gozallik"},{"name":"Yuz uchun niqob","slug":"nex-sinov-15","sku":"NEX-SINOV-15","price":49000,"main_image":"/images/items/15.svg","category_slug":"nex-sinov-gozallik"},{"name":"Kundalik sumka","slug":"nex-sinov-16","sku":"NEX-SINOV-16","price":289000,"main_image":"/images/items/16.svg","category_slug":"nex-sinov-uslub"},{"name":"Hamyon","slug":"nex-sinov-17","sku":"NEX-SINOV-17","price":125000,"main_image":"/images/items/17.svg","category_slug":"nex-sinov-uslub"},{"name":"Quyosh ko‘zoynagi","slug":"nex-sinov-18","sku":"NEX-SINOV-18","price":159000,"main_image":"/images/items/18.svg","category_slug":"nex-sinov-uslub"},{"name":"Sharf","slug":"nex-sinov-19","sku":"NEX-SINOV-19","price":79000,"main_image":"/images/items/19.svg","category_slug":"nex-sinov-uslub"},{"name":"Kichik ryukzak","slug":"nex-sinov-20","sku":"NEX-SINOV-20","price":239000,"main_image":"/images/items/20.svg","category_slug":"nex-sinov-uslub"},{"name":"Keramika finjon","slug":"nex-sinov-21","sku":"NEX-SINOV-21","price":69000,"main_image":"/images/items/21.svg","category_slug":"nex-sinov-oshxona"},{"name":"Choynak","slug":"nex-sinov-22","sku":"NEX-SINOV-22","price":215000,"main_image":"/images/items/22.svg","category_slug":"nex-sinov-oshxona"},{"name":"Oshxona idishlari to‘plami","slug":"nex-sinov-23","sku":"NEX-SINOV-23","price":279000,"main_image":"/images/items/23.svg","category_slug":"nex-sinov-oshxona"},{"name":"Suv grafin","slug":"nex-sinov-24","sku":"NEX-SINOV-24","price":99000,"main_image":"/images/items/24.svg","category_slug":"nex-sinov-oshxona"},{"name":"Nonushta likopchasi","slug":"nex-sinov-25","sku":"NEX-SINOV-25","price":55000,"main_image":"/images/items/25.svg","category_slug":"nex-sinov-oshxona"},{"name":"Suv idishi","slug":"nex-sinov-26","sku":"NEX-SINOV-26","price":79000,"main_image":"/images/items/26.svg","category_slug":"nex-sinov-sport"},{"name":"Yoga gilamchasi","slug":"nex-sinov-27","sku":"NEX-SINOV-27","price":149000,"main_image":"/images/items/27.svg","category_slug":"nex-sinov-sport"},{"name":"Mashq rezinkasi","slug":"nex-sinov-28","sku":"NEX-SINOV-28","price":49000,"main_image":"/images/items/28.svg","category_slug":"nex-sinov-sport"},{"name":"Sport sumkasi","slug":"nex-sinov-29","sku":"NEX-SINOV-29","price":189000,"main_image":"/images/items/29.svg","category_slug":"nex-sinov-sport"},{"name":"Fitnes qo‘lqopi","slug":"nex-sinov-30","sku":"NEX-SINOV-30","price":69000,"main_image":"/images/items/30.svg","category_slug":"nex-sinov-sport"}]'::jsonb) as x(name text, slug text, sku text, price bigint, main_image text, category_slug text)
), inserted_products as (
 insert into products(name, slug, sku, description, price, stock, main_image, category_id, is_published, is_featured)
 select p.name, p.slug, p.sku,
  'Sinov uchun kiritilgan mahsulot. Rasm, narx va ombor qoldig‘i haqiqiy savdo uchun tasdiqlanmagan.',
  p.price, 10, p.main_image, c.id, true, true
 from products_input p join category_map c on c.slug=p.category_slug
 on conflict do nothing returning id
)
select count(*)::int as inserted from inserted_products;
commit;
